import { randomUUID } from 'node:crypto';
import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';

/**
 * A tiny JSON-file-backed book store.
 * Every mutation is written straight back to disk (via a temp file + rename,
 * so a crash mid-write can't corrupt the file).
 */
export function createStore(filePath) {
  let books = load(filePath);

  function persist() {
    mkdirSync(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.tmp`;
    writeFileSync(tmp, JSON.stringify(books, null, 2) + '\n');
    renameSync(tmp, filePath);
  }

  return {
    all() {
      return books;
    },
    reading() {
      return books.filter((b) => !b.finishedAt);
    },
    finished() {
      return books.filter((b) => b.finishedAt);
    },
    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },
    add({ title, author, notes = '' }) {
      const book = {
        id: randomUUID(),
        title: String(title).trim(),
        author: String(author).trim(),
        notes: String(notes).trim(),
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      persist();
      return book;
    },
    finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        persist();
      }
      return book;
    },
  };
}

function load(filePath) {
  let raw;
  try {
    raw = readFileSync(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  const parsed = JSON.parse(raw);
  if (!Array.isArray(parsed)) {
    throw new Error(`${filePath} does not contain a JSON array of books`);
  }
  return parsed;
}

