import http from 'node:http';

const STYLE = `
  :root { color-scheme: light dark; }
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; }
  h1 { font-size: 1.5rem; }
  h2 { font-size: 1.1rem; margin-top: 2rem; border-bottom: 1px solid #8884; padding-bottom: 0.25rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; align-items: baseline; gap: 0.5rem; padding: 0.4rem 0; }
  ul.books .author { opacity: 0.7; }
  ul.books form { margin-left: auto; }
  form.add { display: grid; gap: 0.5rem; margin-top: 0.5rem; }
  form.add input, form.add textarea { font: inherit; padding: 0.4rem; width: 100%; box-sizing: border-box; }
  button { font: inherit; padding: 0.3rem 0.8rem; cursor: pointer; }
  .empty { opacity: 0.6; font-style: italic; }
  .notes { white-space: pre-wrap; }
  a.back { display: inline-block; margin-bottom: 1rem; }
`;

const esc = (s) =>
  String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>${STYLE}</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishForm = book.finishedAt
    ? ''
    : `<form method="post" action="/books/${book.id}/finish"><button>Mark finished</button></form>`;
  return `<li>
    <a href="/books/${book.id}">${esc(book.title)}</a>
    <span class="author">by ${esc(book.author)}</span>
    ${finishForm}
  </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${emptyText}</p>`;
  return `<ul class="books">${books.map(bookItem).join('\n')}</ul>`;
}

function homePage(store) {
  return page(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${bookList(store.reading(), 'Nothing on the go — add a book below.')}

<h2>Finished</h2>
${bookList(store.finished(), 'Nothing finished yet.')}

<h2>Add a book</h2>
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required></label>
  <label>Author <input name="author" required></label>
  <label>Notes <textarea name="notes" rows="4"></textarea></label>
  <button>Add book</button>
</form>`
  );
}

function bookPage(book) {
  const status = book.finishedAt
    ? `Finished on ${esc(book.finishedAt.slice(0, 10))}`
    : `Currently reading`;
  const finishForm = book.finishedAt
    ? ''
    : `<form method="post" action="/books/${book.id}/finish"><button>Mark finished</button></form>`;
  return page(
    book.title,
    `<a class="back" href="/">&larr; All books</a>
<h1>${esc(book.title)}</h1>
<p class="author">by ${esc(book.author)}</p>
<p>${status}</p>
${finishForm}
<h2>Notes</h2>
${book.notes ? `<p class="notes">${esc(book.notes)}</p>` : '<p class="empty">No notes yet.</p>'}`
  );
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 1e6) reject(new Error('body too large'));
    });
    req.on('end', () => resolve(data));
    req.on('error', reject);
  });
}

export function createApp(store) {
  return http.createServer(async (req, res) => {
    const sendHtml = (status, html) => {
      res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
      res.end(html);
    };
    const redirect = (to) => {
      res.writeHead(303, { location: to });
      res.end();
    };

    try {
      const { pathname } = new URL(req.url, 'http://localhost');

      if (req.method === 'GET' && pathname === '/') {
        return sendHtml(200, homePage(store));
      }

      if (req.method === 'POST' && pathname === '/books') {
        const form = new URLSearchParams(await readBody(req));
        const title = (form.get('title') ?? '').trim();
        const author = (form.get('author') ?? '').trim();
        if (!title || !author) {
          return sendHtml(400, page('Missing fields', '<p>Title and author are required. <a href="/">Back</a></p>'));
        }
        const book = store.add({ title, author, notes: form.get('notes') ?? '' });
        return redirect(`/books/${book.id}`);
      }

      const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
      if (req.method === 'GET' && bookMatch) {
        const book = store.get(bookMatch[1]);
        if (!book) return sendHtml(404, page('Not found', '<p>No such book. <a href="/">Back</a></p>'));
        return sendHtml(200, bookPage(book));
      }

      const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);
      if (req.method === 'POST' && finishMatch) {
        const book = store.finish(finishMatch[1]);
        if (!book) return sendHtml(404, page('Not found', '<p>No such book. <a href="/">Back</a></p>'));
        return redirect(`/books/${book.id}`);
      }

      return sendHtml(404, page('Not found', '<p>Page not found. <a href="/">Home</a></p>'));
    } catch (err) {
      console.error(err);
      return sendHtml(500, page('Error', '<p>Something went wrong. <a href="/">Home</a></p>'));
    }
  });
}

