import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../lib/app.js';
import { createStore } from '../lib/store.js';

let dir, dataFile, store, server, base;

beforeEach(async () => {
  dir = mkdtempSync(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'books.json');
  store = createStore(dataFile);
  server = createApp(store);
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((resolve) => server.close(resolve));
  rmSync(dir, { recursive: true, force: true });
});

const addBook = (fields) =>
  fetch(`${base}/books`, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });

describe('book tracker', () => {
  it('shows reading and finished sections on the home page', async () => {
    const html = await (await fetch(base)).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Add a book');
  });

  it('adds a book via the form and lists it under currently reading', async () => {
    const res = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'sandworms' });
    expect(res.status).toBe(303);

    const html = await (await fetch(base)).text();
    expect(html).toContain('Dune');
    expect(html).toContain('Frank Herbert');
  });

  it('serves a shareable per-book page with title, author and notes', async () => {
    const res = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'sandworms &c' });
    const location = res.headers.get('location');
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const html = await (await fetch(base + location)).text();
    expect(html).toContain('Dune');
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('sandworms &amp;c');
    expect(html).toContain('Currently reading');
  });

  it('marks a book as finished', async () => {
    const res = await addBook({ title: 'Dune', author: 'Frank Herbert' });
    const id = res.headers.get('location').split('/').pop();

    const finish = await fetch(`${base}/books/${id}/finish`, { method: 'POST', redirect: 'manual' });
    expect(finish.status).toBe(303);

    expect(store.get(id).finishedAt).toBeTruthy();
    const html = await (await fetch(`${base}/books/${id}`)).text();
    expect(html).toContain('Finished on');
  });

  it('persists books to the JSON file and survives a restart', async () => {
    await addBook({ title: 'Dune', author: 'Frank Herbert' });
    const onDisk = JSON.parse(readFileSync(dataFile, 'utf8'));
    expect(onDisk).toHaveLength(1);
    expect(onDisk[0].title).toBe('Dune');

    const reloaded = createStore(dataFile);
    expect(reloaded.reading()).toHaveLength(1);
    expect(reloaded.reading()[0].title).toBe('Dune');
  });

  it('rejects a book without a title', async () => {
    const res = await addBook({ title: '', author: 'Nobody' });
    expect(res.status).toBe(400);
  });

  it('404s on an unknown book', async () => {
    const res = await fetch(`${base}/books/does-not-exist`);
    expect(res.status).toBe(404);
  });

  it('escapes HTML in user input', async () => {
    const res = await addBook({ title: '<script>alert(1)</script>', author: 'x' });
    const html = await (await fetch(base + res.headers.get('location'))).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
  });
});

